\vspace{-14mm}
\begin{abstract}
One-shot information theory measures often require an optimization over states, but the form of these optimizers can be complicated or depend on the initial problem in nonlinear ways. In this note, we show that in many instances using the marginal instead of the optimal state is sufficiently good and only changes the result by a small factor. We prove that for the Petz--R\'enyi divergence of order $\alpha\in[1/2,1)$, replacing the optimizing state on $B$ by the marginal $\rho_B$ results in a multiplicative overhead of at most $1/\alpha$.
We also show a similar relation for the fidelity, and in the case of pure or quantum-classical states for the sandwiched R\'enyi divergence.
\end{abstract}

\section{Introduction}
Variational expressions of the form
\begin{equation}\label{eq:variational-problem}
\min_{\sigma_B}D_\alpha(\rho_{AB}\|\tau_A\otimes\sigma_B)
\end{equation}
occur naturally in R\'enyi generalizations of conditional entropies and related one-shot information measures~\cite{Tomamichel2016}. 
Although the optimization gives the best value, its optimizer generally depends on the joint state in a nonlinear way. 
In contrast, the marginal $\rho_B$, is canonical and explicit. 
In this note we want to quantify the mistake made by choosing the marginal instead of the optimizer.

Our main result shows that for the Petz--R\'enyi divergence and $\alpha\in[1/2,1)$, the marginal achieves the optimum up to the factor $1/\alpha$:
\begin{equation}
\label{eq:mainresult}
     D_\alpha(\rho_{AB}\| \tau_A\otimes\rho_B) 
    \leq \frac{1}{\alpha} \min_{\sigma_B}
    D_\alpha(\rho_{AB}\| \tau_A\otimes\sigma_B).
\end{equation}
This loss is independent of dimension and tends to vanish as $\alpha\to1$. We prove this by a Schatten-norm variational formula for the optimization over $\sigma_B$, and an operator inequality between a weighted marginal and $\rho_B^\alpha$ obtained from data processing.

We also find that \cref{eq:mainresult} holds for the sandwiched divergence at order $1/2$, where the problem is equivalent to a fidelity maximization, and at $\alpha \in(1/2,1)$ for pure and cq states. 

\section{Preliminaries}\label{sec:preliminaries}

We write $\cS(B)$ for the state space of a quantum system $B$. Powers of positive semidefinite operators are defined on their supports. We define the fidelity of two states $\omega$ and $\xi$ as $F(\omega,\xi)=\|\sqrt{\omega}\sqrt{\xi}\|_1$.
For $\alpha\in(0,1)$, the Petz--R\'enyi divergence is given by
\begin{equation}
   D_\alpha(\rho\|\sigma) =\frac{1}{\alpha-1}\log \tr\left[\rho^\alpha \sigma^{1-\alpha}\right]. 
\end{equation}
Meanwhile, $\alpha'=(1-\alpha)/2\alpha$, the sandwiched--R\'enyi divergence is given by 
\begin{equation}
   \tilde D_\alpha(\rho\|\sigma) =\frac{1}{\alpha-1}\log \tr\left[(\sigma^{\alpha'}\rho\sigma^{\alpha'})^\alpha\right]. 
\end{equation}

\subsection{Tools}
We can prove \cref{eq:mainresult} with the following two lemmas.
\begin{lemma}\label{lem:var}
Let $0<\alpha<1$ and $W_B\ge 0$. Then
\begin{equation}
    \max_{\sigma_B\in\cS(B)}\tr\left[W_B\sigma_B^{1-\alpha}\right] 
    =\tr \left[ W_B^{1/\alpha}\right]^\alpha .
\end{equation}
\end{lemma}

\begin{proof}
For any density operator $\sigma_B$, H\"older's inequality with exponents $p=1/\alpha$ and $q=1/(1-\alpha)$ gives
\begin{align}
\tr\left[W_B\sigma_B^{1-\alpha}\right] \overset{\mathrm{H\ddot older}}&{\leq} \|W_B\|_{1/\alpha} \, \|\sigma_B^{1-\alpha}\|_{1/(1-\alpha)} \\
\overset{\mathrm{Def.}}&{=} \tr \left[ W_B^{1/\alpha}\right]^\alpha \tr \left[ \sigma_B\right]^{1-\alpha} \\
\overset{\tr\, \sigma_B=1}&{=}
\tr \left[  W_B^{1/\alpha}\right]^\alpha .
\end{align}
Equality is attained by
\begin{equation}
    \sigma_B^\star = \frac{W_B^{1/\alpha}}{\tr \, W_B^{1/\alpha}}.
\end{equation}
Therefore
\begin{equation} \label{eq:wb}
    \max_{\sigma_B} \tr\left[W_B\sigma_B^{1-\alpha}\right] 
    = \tr \left[ W_B^{1/\alpha}\right]^\alpha .
\end{equation}
\end{proof}

\begin{lemma}\label{lem:opbound}
For any $\alpha\in (0,1)$ and $\tau_A$ a density operator, define
\begin{equation}
    W_\alpha
=
\tr_A\left[
(\tau_A^{\frac{1-\alpha}{2}}\otimes \id_B)
\rho_{AB}^{\alpha}
(\tau_A^{\frac{1-\alpha}{2}}\otimes \id_B)
\right].
\end{equation}
Then $W_\alpha\leq\rho_B^\alpha$.

\end{lemma}

\begin{proof}
Let $\omega_B$ be a density operator. By data processing of the Petz--Rényi divergence for $\alpha\in(0,1)$~\cite{Petz1986}, we get
\begin{equation}
    D_\alpha(\rho_{AB}\| \tau_A\otimes\omega_B)
\ge
D_\alpha(\rho_B\|\omega_B).
\end{equation}
Since $\alpha-1<0$, this is equivalent to
\begin{align}
\tr\left[\rho_{AB}^{\alpha}(\tau_A\otimes\omega_B)^{1-\alpha}\right]
&\overset{\mathrm{DPI}}{\leq}\tr\left[\rho_B^\alpha\omega_B^{1-\alpha}\right].
\end{align}
Then one gets
\begin{align}
\tr\left[\rho_{AB}^{\alpha}(\tau_A\otimes\omega_B)^{1-\alpha}\right]
&= \tr\left[\rho_{AB}^{\alpha}(\tau_A^{1-\alpha}\otimes\omega_B^{1-\alpha})\right] \\
\overset{\mathrm{cyclicity}}&{=}
\tr\left[(\tau_A^{\frac{1-\alpha}{2}}\otimes\id_B) \rho_{AB}^{\alpha}(\tau_A^{\frac{1-\alpha}{2}}\otimes\id_B)(\id_A\otimes\omega_B^{1-\alpha})\right] \\
\overset{\mathrm{partial\ trace}}&{=} \tr\left[ W_\alpha \omega_B^{1-\alpha} \right].
\end{align}
Hence, for every full-rank density operator $\omega_B$,
\begin{equation}
    \tr\left[ W_\alpha \omega_B^{1-\alpha} \right] \leq \tr\left[ \rho_B^\alpha \omega_B^{1-\alpha} \right].
\end{equation}
Because every positive definite operator $Y_B>0$ is proportional to $\omega_B^{1-\alpha}$ for a suitable full-rank state $\omega_B$, this implies
    $W_\alpha\leq\rho_B^\alpha$.
\end{proof}

\section{Petz--R\'enyi bound}\label{sec:petz}
Now we can state and prove our main result. 
\begin{theorem}\label{thm:petz}
Let $\alpha\in[\frac12,1)$, let $\rho_{AB}$ be a finite-dimensional bipartite state, and let $\tau_A$ be a full-rank density operator. Then
\begin{equation}
    D_\alpha(\rho_{AB}\| \tau_A\otimes\rho_B) 
    \leq \frac{1}{\alpha} \min_{\sigma_B\in\cS(B)}
    D_\alpha(\rho_{AB}\| \tau_A\otimes\sigma_B).
\end{equation}
\end{theorem}

\begin{proof}
Define
\begin{equation}
\label{eq:Wdef}
    W_\alpha = \tr_A\left[ (\tau_A^{\frac{1-\alpha}{2}}\otimes \id_B) \rho_{AB}^{\alpha} (\tau_A^{\frac{1-\alpha}{2}}\otimes \id_B) \right].
\end{equation}
Then, for any state $\sigma_B$,
\begin{align}
D_\alpha(\rho_{AB}\| \tau_A\otimes\sigma_B) \overset{\mathrm{Def}}&{=} \frac1{\alpha-1} \log \tr\left[ \rho_{AB}^{\alpha} (\tau_A\otimes\sigma_B)^{1-\alpha} \right] \\
\overset{\mathrm{Def}}&{=}\frac1{\alpha-1} \log \tr\left[ W_\alpha\sigma_B^{1-\alpha} \right].
\end{align}
Hence, by the variational formula,
\begin{align}
\min_{\sigma_B \in \cS(B)} D_\alpha(\rho_{AB}\| \tau_A\otimes\sigma_B)
\overset{\mathrm{\Cref{lem:var}}}&{=}
\frac{\alpha}{\alpha-1} \log \tr W_\alpha^{1/\alpha}.
\end{align}
Therefore $\frac{1}{\alpha} \min_{\sigma_B} D_\alpha(\rho_{AB}\|\tau_A\otimes\sigma_B)
=
\frac1{\alpha-1} \log \tr[ W_\alpha^{1/\alpha}]$. 
It remains to compare $\tr [W_\alpha^{1/\alpha}]$ with
$\tr[W_\alpha\rho_B^{1-\alpha}]$. Since $\alpha\in[\frac12,1)$, we have
    $0\leq\frac{1-\alpha}{\alpha}\leq1$, and thus $x\mapsto x^{(1-\alpha)/\alpha}$ is operator monotone on $[0,\infty)$. Using~\Cref{lem:opbound},
\begin{align}\label{eq:op}
W_\alpha^{\frac{1-\alpha}{\alpha}}
&\leq
(\rho_B^\alpha)^{\frac{1-\alpha}{\alpha}}
=
\rho_B^{1-\alpha}.
\end{align}
Consequently,
\begin{align}
\tr \, W_\alpha^{1/\alpha}
&=
\tr\left[
W_\alpha W_\alpha^{\frac{1-\alpha}{\alpha}}
\right]
\\
\overset{\mathrm{\Cref{eq:op}}}&{\le}
\tr\left[
W_\alpha\rho_B^{1-\alpha}
\right].\label{eq:hook}
\end{align}
Since $\alpha-1<0$, applying $\frac1{\alpha-1}\log(\cdot)$ reverses the inequality:
\begin{align}\label{eq:log}
\frac1{\alpha-1} \log \tr\left[W_\alpha\rho_B^{1-\alpha} \right]
&\leq \frac{1}{\alpha-1} \log \tr [W_\alpha^{1/\alpha}].
\end{align}
Finally,
\begin{align}D_\alpha(\rho_{AB}\| \tau_A\otimes\rho_B)
\overset{\mathrm{Def}}&{=}
\frac1{\alpha-1} \log \tr\left[ W_\alpha\rho_B^{1-\alpha}\right]
\\
\overset{\mathrm{\Cref{eq:log}}}&{\le}
\frac1{\alpha-1} \log \tr [W_\alpha^{1/\alpha}] \\
\overset{\mathrm{\Cref{lem:var}}}&{=} \frac1\alpha \min_{\sigma_B}
D_\alpha(\rho_{AB}\| \tau_A\otimes\sigma_B).
\end{align}
This proves the claim.
\end{proof}

\begin{remark}
    In the limit $\alpha \to 1$, the theorem holds as well and it is known that the optimizer is the marginal.
\end{remark}

\begin{remark}[Non-full-rank states]\label{rem:cont}
The full-rank assumption on $\tau_A$ is only used to avoid support
technicalities. The statement extends to arbitrary density operators
$\tau_A\ge 0$ by a standard continuity argument.
\end{remark}
\begin{proof}
    See~\cref{app:1}
\end{proof}

\begin{remark}[Tightness of the bound]\label{rem:tight}
The bound is tight in certain circumstances, even for classical $\rho_{AB}$. Indeed, consider the distribution $P_{XY}$ with $\mathcal X=\mathcal Y=\{0,\dots,n-1\}$ for some integer $n$ such that $P_{XY}(0,0)=p$ with $p\in (0,1)$ and $P_{X,Y}(x,y)=(1-p)/(n^2-1)$ for $(x,y)\neq (0,0)$. 
Then for any $\alpha\in [1/2,1)$, $p\in (0,1)$, and $U_X$ the uniform distribution, we have 
\begin{equation}
    \lim_{n\to \infty} \frac{1}{\alpha} \min_{R_Y} D_\alpha(P_{XY}\|U_X\times R_Y)-D_\alpha(P_{XY}\|U_X\times P_Y)=0\,. 
\end{equation}
\end{remark}
\begin{proof}
    It is enough to show that the inequality \cref{eq:hook} is saturated.
    The marginal $P_Y$ is defined by $P_Y(0)=p+(1-p)/(n+1)$ and $P_Y(y)=(1-p)n/(n^2-1)$ for $y\neq 0$. 
    For convenience, define $q=(1-p)n/(n^2-1)$.
    Meanwhile $W_Y(y)=n^{\alpha-1}\sum_{x\in \mathcal X}P_{XY}(x,y)^\alpha$ from \cref{eq:Wdef}.
    Using the definition of $P_{XY}$, this expression is just $W_Y(0)=n^{\alpha-1}(p^\alpha+(n-1)((1-p)/(n^2-1))^\alpha)$ and $W_Y(y)=q^\alpha$ for $y\neq 0$. 
    Observe that $W_Y^{1/\alpha}$ and $W_YP_Y^{1-\alpha}$ are both equal to $q$ for  $y\neq 0$. The bound then implies that $W_Y^{1/\alpha}(0)\leq W_Y(0)P_Y(0)^{1-\alpha}$, so to complete the proof it is sufficient to show that $\lim_{n\to \infty} W_Y(0)P_Y(0)^{1-\alpha}=0$. The limit of $P_Y(0)$ is just $p$, while the limit of $W_Y(0)$ vanishes as $1/n^\alpha$. 
\end{proof}

\section{Sandwiched--R\'enyi bound}\label{sec:fidelity}
One may wonder if \cref{eq:mainresult} also holds in the case of the sandwiched relative entropy. 
We can show this for arbitrary states $\rho_{AB}$ when $\alpha=\frac{1}{2}$, i.e.\ for the fidelity, as well as for pure and QC states for $\alpha\in (1/2,1)$. 

\subsection{Fidelity bound}
For the fidelity bound we make use of the following operator Cauchy--Schwarz statement. 
\begin{lemma}[Operator Cauchy--Schwarz]\label{lem:cauchy}
Let $t_i\ge0$ with $\sum_i t_i=1$, and let $Y_i$ be linear maps. Then
\begin{equation}
\left(\sum_i \sqrt{t_i}Y_i\right)
\left(\sum_j \sqrt{t_j}Y_j\right)^*
\le
\sum_i Y_iY_i^* .
\end{equation}
\end{lemma}

\begin{proof}
For every vector $\ket{\varphi}$,
\begin{align}
\left\|
\left(\sum_i \sqrt{t_i}Y_i\right)^*
\ket{\varphi}
\right\|^2
&=
\left\|
\sum_i \sqrt{t_i}Y_i^*\ket{\varphi}
\right\|^2
\\
\overset{\text{Cauchy--Schwarz}}&{\leq}
\left(\sum_i t_i\right)
\left(\sum_i \|Y_i^*\ket{\varphi}\|^2\right)
\\
&=
\sum_i
\langle\varphi|Y_iY_i^*\ket{\varphi}
=
\bra{\varphi}
\sum_iY_iY_i^*
\ket{\varphi}.
\end{align}
Since this holds for every $\ket{\varphi}$, the operator inequality follows.
\end{proof}

\begin{lemma}\label{lem:marginal}
    For any unitary $U_{AB}$, positive operator $\rho_{AB}$ and density operator $\tau_A$, define  
    \begin{equation}
        X_U=\tr_A\left[
(\sqrt{\tau_A}\otimes \id_B)\sqrt{\rho_{AB}}\,U_{AB}
\right]\,.
    \end{equation}
    Then $X_U X_U^*\leq \rho_B$.
\end{lemma}
\begin{proof}
    Let $\{\ket{i}\}$ be the eigenbasis of $\tau_A$ so that $\tau_A=\sum_i t_i \ketbra i_A$ and define
\begin{equation}
Y_i
=
(\bra{i}_A\otimes \id_B)\sqrt{\rho_{AB}}\,U _{AB}(\ket{i}_A\otimes \id_B).
\end{equation}
Then, by definition, $X_U=
\sum_i \sqrt{t_i}\,Y_i$. 
Hence
\begin{align}
X_UX_U^*
&=
\left(\sum_i\sqrt{t_i}Y_i\right)
\left(\sum_j\sqrt{t_j}Y_j\right)^*
\\
\overset{\text{\Cref{lem:cauchy}}}&{\leq}
\sum_iY_iY_i^*
\\
\overset{\text{
Def }Y_i}&{=}
\sum_i
(\bra{i}_A\otimes \id_B)
\sqrt{\rho_{AB}}\,U_{AB} (\ketbra i_A \otimes \id_B) U_{AB}^*
\sqrt{\rho_{AB}}
(\ket{i}_A\otimes \id_B)
\\
&\leq
\sum_i
(\bra{i}_A\otimes \id_B)
\rho_{AB}
(\ket{i}_A\otimes \id_B)
\\
\overset{\text{Def partial trace}}&{=}
\rho_B.
\end{align}
\end{proof}

Now we can state and prove the fidelity bound. 
\begin{theorem}\label{prop:fidelity}
    Let $\rho_{AB}$ and $\tau_A$ be finite-dimensional states. Then
    \begin{equation}
    \label{eq:fidelitybound}
        F(\rho_{AB},\tau_A \otimes \rho_B) \geq \max_{\sigma_B} F(\rho_{AB},\tau_A\otimes \sigma_B) ^2   \,. 
    \end{equation}
\end{theorem}

\begin{proof}
For unitary $U_{AB}$, define
\begin{equation}
X_U
=
\tr_A\left[
(\sqrt{\tau_A}\otimes \id_B)\sqrt{\rho_{AB}}\,U_{AB}
\right].
\end{equation}
The proof proceeds by showing 
\begin{align}
    F(\rho_{AB},\tau_A \otimes \rho_B) &\geq 
\max_U \|X_U\|_2^2\qquad\text{and}\label{eq:step1}\\
\max_U \|X_U\|_2^2&\geq \max_{\sigma_B}
F(\rho_{AB},\tau_A\otimes\sigma_B)^2\label{eq:step2}
\end{align}
The latter inequality is the simpler one and involves Cauchy-Schwarz for the Hilbert-Schmidt inner product. 
For arbitrary $\sigma_B$,
\begin{align}
F(\rho_{AB},\tau_A\otimes\sigma_B)
\overset{\text{Def}}&{=}
\left\|
(\sqrt{\tau_A}\otimes\sqrt{\sigma_B})
\sqrt{\rho_{AB}}
\right\|_1
\\
\overset{\text{polar decomposition}}&{=}
\max_U
\left|
\tr\left[
(\sqrt{\tau_A}\otimes\sqrt{\sigma_B})
\sqrt{\rho_{AB}}\,U_{AB}
\right]
\right|
\\
\overset{\text{Def }X_U}&{=}
\max_U
\left|
\tr\left[
\sqrt{\sigma_B}X_U
\right]
\right|
\\
\overset{\text{Hilbert--Schmidt Cauchy--Schwarz}}&{\leq}
\max_U
\|\sqrt{\sigma_B}\|_2\|X_U\|_2
\\
\overset{\tr\sigma_B=1}&{=}
\max_U \|X_U\|_2 .
\end{align}
Therefore
\begin{equation} \label{eq:fid2}
   \max_{\sigma_B}
F(\rho_{AB},\tau_A\otimes\sigma_B)^2
\le
\max_U \|X_U\|_2^2. 
\end{equation}

Now we turn to \cref{eq:step1} which relies on the operator Cauchy-Schwarz through \Cref{lem:marginal}. 
 Fix an arbitrary unitary $U_{AB}$ and take a
right polar decomposition of $X_U$:
\begin{equation}
X_U=K_UW_U,
\qquad
K_U=(X_UX_U^*)^{1/2}\ge0.
\end{equation}
Extending $W_U$ to a unitary on $B$ if necessary, define
$V=U(\id_A\otimes W_U^*)$.
Then
\begin{align}
X_V = \tr_A\left[
(\sqrt{\tau_A}\otimes\id_B)
\sqrt{\rho_{AB}}\,U(\id_A\otimes W_U^*)
\right]
\overset{\text{
Def }X_U}{=}
X_UW_U^*
\overset{\text{polar decomposition}}{=}
K_U .
\end{align}

Using $V$ in the variational expression for
$F(\rho_{AB},\tau_A\otimes\rho_B)$ gives
\begin{align}
F(\rho_{AB},\tau_A\otimes\rho_B)
\overset{\text{Def}}&{=}
\left\|
(\sqrt{\tau_A}\otimes\sqrt{\rho_B})
\sqrt{\rho_{AB}}
\right\|_1
\\
\overset{\text{}}&{=}
\max_V
\left|
\tr\left[
(\sqrt{\tau_A}\otimes\sqrt{\rho_B})
\sqrt{\rho_{AB}}\,V
\right]
\right|
\\
\overset{\text{choose }V=U(\id_A\otimes W_U^*)}&{\ge}
\left|
\tr\left[
(\sqrt{\tau_A}\otimes\sqrt{\rho_B})
\sqrt{\rho_{AB}}\,U_{AB}(\id_A\otimes W_U^*)
\right]
\right|
\\
\overset{\text{Def }X_U}&{=}
\left|
\tr\left[
\sqrt{\rho_B}X_U W^*_U
\right]
\right|
\\
\overset{\text{polar decomp}}&{=}
\tr\left[
\sqrt{\rho_B}K_U
\right].
\end{align}

By~\Cref{lem:marginal} 
$K_U^2=X_UX_U^*\le \rho_B$. 
And since $x\mapsto \sqrt{x}$ is operator monotone for positive $x$,
$K_U\le \sqrt{\rho_B}$.
Therefore $\tr\left[
\sqrt{\rho_B}K_U
\right]
\geq \tr[K_U^2]
$, and so we have 
\begin{align}
F(\rho_{AB},\tau_A\otimes\rho_B)
&\geq \tr[\sqrt{\rho_B}K_U] 
\geq
\tr[K_U^2]
=
\|X_U\|_2^2\,.
\end{align}
Since this inequality holds for every unitary $U$, \cref{eq:step1} follows. 
\end{proof}

\subsection{Special cases}\label{sec:special}
For $\alpha\in (1/2,1)$ and $\rho_{AB} = \ketbra \psi$ or classical $B$ system,  we can show more generally
\begin{equation}
    \Tilde{D}_{\alpha}(\rho_{AB} \| \tau_A \otimes \rho_B) \leq \frac{1}{\alpha}  \min_{\sigma_B} \Tilde{D}_{\alpha}(\rho_{AB} \| \tau_A \otimes \sigma_B)\,.
\end{equation}
Observe that this is equivalent to 
\begin{equation}\label{eq_Q}
    \tr\left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}} \rho_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right] 
    \geq 
    \max_{\sigma_B} \tr \left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}} \rho_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right]^{1/\alpha}\,. 
\end{equation}

\noindent
\textbf{Pure states:}
\begin{proof}
    In the case $\rho_{AB} = \ketbra \psi_{AB}$, we have
    \begin{equation}\label{eq_lhs_pure}
        \tr\left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}} \ketbra \psi_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right] = \tr\left[\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}} \ketbra \psi_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}}\right]^{\alpha} \,. 
    \end{equation}
    Define
    \begin{equation}
        T_B = \tr_A \left[\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \id_B \ketbra\psi_{AB} \,\, \tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \id_B  \right]
    \end{equation}
    and note that $0 \leq T_B \leq \rho_B$ since $\tau_A^{\frac{1-\alpha}{\alpha}} \leq \id_A$. 
    Then the left hand side of~\cref{eq_Q} becomes
    \begin{align}
        \tr\left[\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}} \ketbra \psi_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}}\right]^{\alpha}  &= \tr[\rho_B^{\frac{1-\alpha}{\alpha}}T_B]^\alpha \\
        \overset{T_B \leq \rho_B, \, \text{monotonicity}}&{=}\tr[T_B^{\frac{1}{\alpha}}]^{\alpha} \\
        &= \norm{T_B}_{1/\alpha}\,. 
    \end{align}
 Analogously, we get for the right hand side
    \begin{align}
        \max_{\sigma_B} \tr \left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}} \ketbra \psi_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right]^{1/\alpha} &= \max_{\sigma_B} \tr \left[\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}} \ketbra \psi_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}}\right] \\
        &= \max_{\sigma_B} \tr \left[ \sigma_B^{\frac{1-\alpha}{\alpha}}T_B \right] \\
        \overset{\text{\Cref{lem:var}}}&{=}  \tr \left[ T_B^{\frac{\alpha}{2\alpha -1}}\right]^{\frac{2\alpha-1}{\alpha}} \\
        &= \norm{T_B}_{\frac{\alpha}{2\alpha -1}}\,.
    \end{align}
    And since $\frac{\alpha}{2\alpha -1}\geq\frac{1}{\alpha}$, \cref{eq_Q} follows from $\norm{T_B}_{1/\alpha} \geq \norm{T_B}_{\frac{\alpha}{2\alpha -1}}$.
\end{proof}

\noindent
\textbf{QC states:}
\begin{proof}
Set $\rho_{AB} = \sum_i p_i \rho_A^i \otimes \ketbra i_B$ and let 
 $P$ be the pinching map onto the basis $\ket{i}$. By data processing, we have
    \begin{equation}
        \Tilde{D}_\alpha(\rho_{AB} \| \tau_A \otimes \sigma_B) \geq \Tilde{D}_\alpha(\rho_{AB} \| \tau_A  \otimes P(\sigma_B)) \,.
    \end{equation}
    We can therefore assume without loss of generality that  $\sigma_B$ is diagonal, so set $\sigma_B = \sum_i q_i \ketbra i_B$. 

    For the left hand side of~\cref{eq_Q} we then get 
    \begin{equation}
        \tr\left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}} \rho_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \rho_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right] = \sum_i p_i \tr\left[\left( \tau_A^{\frac{1-\alpha}{2\alpha}} \rho_A^i \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \right)^{\alpha} \right]\,. 
    \end{equation}

    On the other hand, for the right-hand side we have 
    \begin{equation}
        \max_{\sigma_B} \tr \left[\left(\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}} \rho_{AB} \,\,\tau_A^{\frac{1-\alpha}{2\alpha}} \otimes \sigma_B^{\frac{1-\alpha}{2\alpha}}\right)^{\alpha}\right]^{1/\alpha}
        = 
        \max_{q_i}
        \left(\sum_i q_i^{1-\alpha} p_i^\alpha \tr \left[ \left( \tau^{\frac{1-\alpha}{2\alpha}} \rho_A^i \, \, \tau^{\frac{1-\alpha}{2\alpha}}\right)^\alpha\right]\right)^{1/\alpha}\,.
    \end{equation}
    Defining $t_i = p_i^\alpha \tr \left[ \left( \tau^{\frac{1-\alpha}{2\alpha}} \rho_A^i \, \, \tau^{\frac{1-\alpha}{2\alpha}}\right)^\alpha\right]$ and $T_B = \sum_i t_i \ketbra i_B$, this can be further simplified to 
    \begin{equation}
        \max_{\sigma_B} \tr[\sigma_B^{1-\alpha}T_B]^{1/\alpha} \overset{\text{\Cref{lem:var}}}{=} \tr \left[ T_B^{1/\alpha}\right] = \sum_i t_i^{1/\alpha} \,.
    \end{equation}
    Since $x_i \coloneqq \tr \left[ \left( \tau^{\frac{1-\alpha}{2\alpha}} \rho_A^i \, \, \tau^{\frac{1-\alpha}{2\alpha}}\right)^\alpha\right] \leq 1$, we have
    \begin{equation}
        \sum_i p_i x_i \geq \sum_i p_i x_i^{1/\alpha} = \sum_i t_i^{1/\alpha}.
    \end{equation}
    This implies the claim.
\end{proof}

\section{Discussion}\label{sec:discussion}
\Cref{thm:petz} shows that using the marginal is almost as good as the optimizer. The restriction $\alpha\geq1/2$ enters through operator monotonicity of $x\mapsto x^{(1-\alpha)/\alpha}$.
Based on the results in \Cref{sec:fidelity}, we believe
\begin{equation}\label{eq_conjec}
    \Tilde{D}_{\alpha}(\rho_{AB} \| \tau_A \otimes \rho_B) \leq \frac{1}{\alpha}  \min_{\sigma_B} \Tilde{D}_{\alpha}(\rho_{AB} \| \tau_A \otimes \sigma_B)
\end{equation}
holds for general states as well. 
While being unable to show this in general, 
observe that a weaker bound follows from the Araki--Lieb--Thirring inequality~\cite{Araki1990} and its reverse, which imply \cite{Iten_2017}
\begin{equation}
\widetilde D_\alpha(\rho\|\sigma)
\leq D_\alpha(\rho\|\sigma)
\leq\frac1\alpha\widetilde D_\alpha(\rho\|\sigma).
\end{equation}
Combined with \Cref{thm:petz}, this gives
\begin{equation}
\widetilde D_\alpha(\rho_{AB}\|\tau_A\otimes\rho_B)
\leq\frac1{\alpha^2}\min_{\sigma_B}
\widetilde D_\alpha(\rho_{AB}\|\tau_A\otimes\sigma_B)\,.
\end{equation}

