\begin{algorithmic}[1]
\For{$b = 1$ to $m$} \Comment{Iterate over measurement patterns}
    \State Generate $\mathbf{x}_b = (x_{b,1}, \ldots, x_{b,n})$ \Comment{Random $n$-trit string}
    \State $x_{b,i} \in \{0, 1, 2\}$ for $i = 1, \ldots, n$
    \Comment{0: Z, 1: X, 2: Y basis}
    \For{$u = 1$ to $r$}
        \Comment{Repeat each pattern $r$ times}
        \State $\ket{\psi} \leftarrow \text{Oracle()}$
        \Comment{Obtain copy of unknown state}
        \For{$i = 1$ to $n$}
            \Comment{Measure each qubit}
            \State Measure qubit $i$ in basis specified by $x_{b,i}$
            \If{$x_{b,i} = 0$}
                \State Measure in Z basis
            \ElsIf{$x_{b,i} = 1$}
                \State Measure in X basis
            \ElsIf{$x_{b,i} = 2$}
                \State Measure in Y basis
            \EndIf
            \State $m_{u,b,i} \leftarrow$ measurement outcome
            \Comment{Record result}
        \EndFor
    \EndFor
\EndFor
