\textbf{Algorithm 2:Identifying Stabilizer Generators}

\vspace{4pt}
\hrule height 0.5pt
\vspace{2pt}

\begin{algorithmic}[1]
\Require  
$(\mathcal{X})_b$: Measurement pattern matrix
\newline
$(\mathcal{M})_{u,b}$: Measurement outcome matrix
\Ensure
$G$: Set of $n$ generators of the stabilizer state, including their respective signs

\State $G \gets \emptyset$ \Comment{Initialize generator set}
\For{$b = 1$ to $m$} \Comment{Iterate over measurement patterns}
    \State $\mathcal{S}_w \gets \left\{ S \subseteq \{1,\dots,n\} : |S| \le w \right\}$ \Comment{Generate subset of the power set with Hamming weights at most $w$}
    \For{each subset $s \in \mathcal{S}_w$}
        \State $P \gets \{0: 0, 1: 0\}$ 
        \Comment{Initialize parity counts}
        \For{$u = 1$ to $r$} \Comment{Iterate over repetitions}
            \State parity $\gets \bigoplus_{q \in s} (M)_{u,b,q}$ \Comment{Calculate parity}
            \State $P[\text{parity}] \gets P[\text{parity}] + 1$ \Comment{Update parity counts}
        \EndFor
        \If{$|P[0] - P[1]| > r/4$} \Comment{Check for significant difference}
            \State sign $\gets$ `+' if $P[0] > P[1]$ else `-' \Comment{Determine stabilizer sign}
            \State generator $\gets$ sign
            \For{$i = 1$ to $n$} \Comment{Construct stabilizer generator}
                \If{$i \in s$}
                    \State generator $\gets$ append$\big($generator , PauliOperator($(X)_{b,q}$)$\big)$
                \Else
                    \State generator $\gets$ append$\big($generator , `I'$\big)$
                \EndIf
            \EndFor
            \State $G \gets G \cup \{\text{generator}\}$ \Comment{Add generator to set}
        \EndIf
    \EndFor
\EndFor
\State \Return $G$ \Comment{Return the generator set}
\end{algorithmic}

