\subsection{Proof of Theorem \ref{th:Nbound}}\label{sec:proof1}
\begin{proof}
 Of all possible Pauli operators of weight at most $w$, the probability of learning $G_1$ is $1/A$, therefore, the probability of not learning $G_1$ is $1-1/A$.
After $N$ queries, the probability of not learning $G_1$ is $(1-1/A)^N$.
We need to find all $g$ stabilizer generators, so our algorithm fails if we do not find any one of $G_i, \; i=1,\dots, g$. The probability of this happening is 
\begin{equation}\label{eq:probfail}
 \Pr(\text{fail}) =   g \left( 1-\frac{1}{A}\right)^N.
\end{equation}
Using the inequality $(1-\frac{1}{A}) \leq e^{-1/A}$ for $A>1$, we get
\begin{equation}
\Pr(\text{fail}) \leq g e^{-N/A}.
\end{equation}
Now, let the target worst-case failure probability be $\delta$,
then let us impose the inequality
\begin{equation}
g e^{-N/A} \le \delta.
\end{equation}
Since the exponential function is a monotone function, we take the natural logarithm of both sides of the above inequality to get
\begin{align}
 \ln g - N/A \le \ln \delta
\end{align}
which is equivalent to 
\begin{align}
    - N/A  \le - \ln g + \ln \delta,
\end{align}
therefore
\begin{align}
    N  \ge A \ln g + A \ln(1/\delta).
\end{align}
For $\delta =1 / g$, we get
\begin{align}
    N  \ge 2  A \ln g .
\end{align}
\end{proof}

\subsection{Proof of Lemma \ref{lem:q}}\label{sec:proof2}
\begin{proof}
When performing a product measurement of a Pauli operator of weight $w$ (that is, a single-qubit measurement on each of the $w$ qubits in its support), if an even number of bit-flip errors occur, we will still obtain the correct measurement outcome. The probability of an incorrect measurement outcome is therefore the sum of the probabilities of any odd number of bit-flip errors occurring
\begin{equation}
\begin{split}
    q &= \sum_{\substack{ 1 \leq k\leq w \\ k \; \text{odd}}} \binom{w}{k}p^k(1-p)^{w-k}.
\end{split}
\end{equation}
By the method of generating functions, this is just 
\begin{align}
  q=   ( (1-p) + p)^w - ((1-p)-p)^w ) /2,
\end{align}
which when simplified gives the result.
\end{proof}

\subsection{Proof of Lemma \ref{lem:paccept}}\label{sec:proof3}
\begin{proof}
Let us first look at the case $Q\in\left\{ I,X,Y,Z \right\}^{\otimes n}$. Then the expected even parity count, when no parity errors occur, is $\mathbb{E}\left( P[0] \right) = r$ and the expected odd parity count is $\mathbb{E}\left( P[1] \right) = 0$. However, when we allow for parity errors to occur with probability $q$, then the expected parity counts become $\mathbb{E}\left( P[0] \right) = r(1-q)$ and $\mathbb{E}\left( P[1] \right) = rq$. We assume that $q$ is small and therefore $P[0]>P[1]$, therefore we can calculate the probability that $Q$ is rejected
\begin{equation}
\begin{split}
\Pr \left( |P[0]-P[1]|\leq \frac{r}{4} \right) &= \Pr\left( 2P[0]-r \leq \frac{r}{4} \right)\\
&=\Pr\left( P[0] \leq \frac{5r}{8} \right).
\end{split}
\end{equation}
We can then use the multiplicative Chernoff bound \cite{mitzenmacher2017probability}
\begin{equation}\label{eq:chernoff}
\Pr(X\leq (1-\delta)\mu)\leq \left( \frac{e^{-\delta}}{(1-\delta)^{1-\delta}} \right)^{\mu},
\end{equation}
where we choose $\mu = \mathbb{E}(P[0]) = r(1-q)$ and $\delta = 1-\tfrac{5}{8(1-q)}$ to get
\begin{equation}
\Pr\left( P[0]\leq \frac{5r}{8} \right) \leq c_q^{5r/8}.
\end{equation}
Similarly, if $Q\in-\left\{ I,X,Y,Z\right\}^{\otimes n}$ then $\mathbb{E}(P[1]) = r(1-q)$ and $\mathbb{E}(P[0]) = rq$. By the same reasoning we find that 
\begin{equation}
\Pr\left( P[1] \leq \frac{5r}{8} \right) \leq c_q^{5r/8}.
\end{equation}
Therefore if $Q\in \pm \left\{ I,X,Y,Z \right\}^{\otimes n}$ then the probability that our algorithm will correctly accept $Q$ as an element of the stabilizer group $G$ is 
\begin{equation}
\Pr(\text{accept}|Q\in G) \geq 1-2 c_q^{5r/8}.
\end{equation}
\end{proof}

\subsection{Proof of Lemma \ref{lem:preject}}\label{sec:proof4}
\begin{proof}
If we take measurements of $r$ copies of a Pauli operator $Q \notin G$, parity errors are equally likely to occur to both the even and odd parities, therefore the expectation values of the parity counts are $\mathbb{E}(P[0]) = \mathbb{E}(P[1]) = r/2$. There are two possible cases, either $P[0]>P[1]$ or $P[1]>P[0]$. Starting with the case $P[0]>P[1]$
\begin{equation}
\begin{split}
\Pr\left(|P[0]-P[1]|\leq \frac{r}{4} \right) &= \Pr\left( 2P[0] - r \right)\\
&= \Pr\left( P[0]\leq \frac{5r}{8} \right).
\end{split}
\end{equation}
Then, using the multiplicative Chernoff bound in eq. \eqref{eq:chernoff} with $\mu = \mathbb{E}(P[0]) = r/2$ and $\delta = 1/4$, we get
\begin{equation}
\Pr\left( P[0] \leq \frac{5r}{8}\right) \leq \left(\frac{64}{27 e}  \right)^{r/8}.
\end{equation}
For the case of $P[1]>P[0]$, similarly we get
\begin{equation}
\begin{split}
\Pr\left( |P[0]-P[1]|\leq \frac{r}{4} \right)&= \Pr\left( 2P[1]-r\leq \frac{r}{4} \right)\\
&= \Pr\left( P[1]\leq \frac{5r}{8} \right)\\
&\leq \left(\frac{64}{27 e}  \right)^{r/8}.
\end{split}
\end{equation}
Therefore, the probability of rejecting a Pauli operator, $Q$, that is not an element of the stabilizer group $G$ is
\begin{equation}
\Pr\left( \text{reject}| Q\notin G \right) \geq 1-2\left(\frac{64}{27 e}  \right)^{r/8}.
\end{equation}
\end{proof}

\subsection{Proof of Theorem \ref{th:pfailure}}\label{sec:proof6}
\begin{proof}
Let us take the coarse upper bound $A<w(3n)^w$ which comes from the fact that
\begin{align*}
\binom{n}{k} \leq n^k  \implies \binom{n}{k}3^k \leq (3n)^k \implies \sum_{k=1}^w \binom{n}{k}3^k \leq w(3n)^w.
\end{align*}
We will use \eqref{pfail} for the upper bound on the probability of failure. 
Noting that $64/(27e)<9/10$, the failure probability is bounded above by $n^{-2w}$ if the following inequality holds
\begin{equation}
 4w^2(3n)^{2w} \ln(n) (0.9)^{r/8} \le n^{-2w}.
\end{equation}
Taking the natural logarithm of both sides gives
\begin{equation}
\ln(4w^2)+2w\ln(3n)+\ln(\ln(n))+\frac{r}{8}\ln\left(\frac{9}{10}\right) \leq -2w\ln(n) , 
\end{equation}
therefore 
\begin{equation}
\frac{r}{8}\ln\left(\frac{9}{10}\right) \leq -2w\ln(3n^2) - \ln(4w^2)-\ln(\ln(n)).
\end{equation}
Then, noting that $\ln(9/10)<0$, we can find a bound on $r$
\begin{equation}
\begin{split}
r &\geq \frac{-8\left( 2w\ln(3n^2) + \ln(4w^2)+\ln(\ln(n)) \right)}{-\ln(10/9)}\\
&\geq 76\left(2w\ln(3n^2) + \ln(4w^2)+\ln(\ln(n)) \right),
\end{split}
\end{equation}
proving the lemma.
\end{proof}

\section{Conclusions}
In conclusion, we have presented an algorithm for learning the stabilizer generators that define any stabilizer code from
$N$ states belonging to the codespace. Our approach requires no prior knowledge of the code's structure beyond access to copies of states in the codespace, making it broadly applicable across different families of stabilizer codes. 
We defined the probability of a parity error occurring, which allowed us to obtain a bound on the algorithm's overall probability of success.
This method is particularly successful for qLDPC codes whose stabilizer generators are all of weight at most $w$. To learn the stabilizer generators with probability $1/g$, it suffices to take $N\geq A \ln(g)$, where $A$ is the number of Pauli operators of weight at most $w$. Thus, the learning problem remains tractable for codes with sparse stabilizer generators.
We have also shown that with only polylogarithmically many copies of the stabilizer states, we may verify any stabilizer qLDPC code without prior knowledge of its generators.
An interesting open question is whether similar learning algorithms can be developed for non-stabilizer quantum codes.

